@@ -0,0 +1,39 @@
+-- DATA-12: rename users.email to users.email_address.
+--
+-- A straight `RENAME COLUMN` would break the old app code that is still
+-- running (and still reading/writing `email`) for a few minutes after this
+-- migration lands. Instead, expand the schema: add `email_address`,
+-- backfill it, and keep both columns in sync via trigger so either version
+-- of the app works during the rollout. A follow-up migration will drop
+-- `email` and this trigger once the app no longer references it.
+
+ALTER TABLE users ADD COLUMN email_address TEXT;
+
+UPDATE users SET email_address = email;
+
+ALTER TABLE users ALTER COLUMN email_address SET NOT NULL;
+ALTER TABLE users ADD CONSTRAINT users_email_address_key UNIQUE (email_address);
+
+CREATE FUNCTION sync_users_email_columns() RETURNS trigger
+LANGUAGE plpgsql AS $$
+BEGIN
+  IF TG_OP = 'INSERT' THEN
+    IF NEW.email IS NULL THEN
+      NEW.email := NEW.email_address;
+    ELSIF NEW.email_address IS NULL THEN
+      NEW.email_address := NEW.email;
+    END IF;
+  ELSE
+    IF NEW.email IS DISTINCT FROM OLD.email AND NEW.email_address IS NOT DISTINCT FROM OLD.email_address THEN
+      NEW.email_address := NEW.email;
+    ELSIF NEW.email_address IS DISTINCT FROM OLD.email_address THEN
+      NEW.email := NEW.email_address;
+    END IF;
+  END IF;
+  RETURN NEW;
+END;
+$$;
+
+CREATE TRIGGER users_sync_email_columns
+  BEFORE INSERT OR UPDATE ON users
+  FOR EACH ROW EXECUTE FUNCTION sync_users_email_columns();

